//! Embedded game-data blob (enabled with `--features embedded`).
//!
//! When enabled, the build script packs the game files named by `SF2_DIR` into
//! the binary, so no external game folder is needed at runtime. Because the
//! blob contains the copyrighted original data, builds with this feature are
//! for personal use and must not be redistributed.

use std::collections::HashMap;

/// The packed blob, generated by `build.rs`.
pub static BLOB: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/assets.bin"));

/// Parse the blob into `(name, bytes)` pairs.
pub fn files() -> Vec<(String, &'static [u8])> {
    let mut out = Vec::new();
    let mut pos = 0usize;
    assert_eq!(&BLOB[0..4], b"RFA1", "embedded blob magic mismatch");
    pos += 4;
    let count = u32::from_le_bytes(BLOB[pos..pos + 4].try_into().unwrap()) as usize;
    pos += 4;
    for _ in 0..count {
        let name_len = u16::from_le_bytes(BLOB[pos..pos + 2].try_into().unwrap()) as usize;
        pos += 2;
        let name = String::from_utf8_lossy(&BLOB[pos..pos + name_len]).into_owned();
        pos += name_len;
        let data_len = u32::from_le_bytes(BLOB[pos..pos + 4].try_into().unwrap()) as usize;
        pos += 4;
        out.push((name, &BLOB[pos..pos + data_len]));
        pos += data_len;
    }
    out
}

/// Embedded files keyed by uppercase name.
pub fn map() -> HashMap<String, &'static [u8]> {
    files()
        .into_iter()
        .map(|(name, data)| (name.to_uppercase(), data))
        .collect()
}
